/* From Uiverse.io by Lakshay-art - Tags:  */
.__UIV_SCOPE__ .card::before {
  content: "";
  background: rgb(202, 26, 114);
  position: absolute;
  /* inset: 0; */
  z-index: -100;
}

.__UIV_SCOPE__ .card {
  width: 300px;
  height: 300px;
  zoom: .8;
}

.__UIV_SCOPE__ .heading {
  font-size: 24px;
  color: white;
  text-shadow: -1px 2px 0px #fff,
				  -1px -2px 12px #fff;
  position: absolute;
  top: calc(50% - 190px);
}

.__UIV_SCOPE__ .heading span {
  color: hotpink;
  text-shadow: -1px 2px 0px #ff69b4,
				  -1px -2px 12px hotpink;
}

.__UIV_SCOPE__ button {
  border: 2px #ff69b4 solid;
  padding: 10px 80px;
  background-color: #ff69b422;
  border-radius: 30px;
  color: #ff69b4;
  font-weight: 900;
  font-size: 16px;
  margin-top: 345px;
}

.__UIV_SCOPE__ button:hover {
  background-color: #ff69b444;
}

.__UIV_SCOPE__ .item--create::before {
  content: "";
  background-color: rgb(69, 1, 37);
  width: 120px;
  height: 120px;
  position: absolute;
  top: 0px;
  z-index: -1;
}

.__UIV_SCOPE__ .item--create {
  width: 120px;
  height: 125px;
  position: absolute;
  top: calc(50% - 115px);
  left: calc(50% - 65px);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 45px;
  transition: padding-top 0.5s ease-out;
  -webkit-mask-image: url('data:image/svg+xml;base64,');
  z-index: 100;
  -webkit-mask-repeat: no-repeat;
}

.__UIV_SCOPE__ .item--create svg {
  height: 50px !important;
  width: 50px !important;
  margin-bottom: 10px;
  transition: height 0.5s ease-out,width 0.5s ease-out,margin-bottom 0.5s ease-out;
}

.__UIV_SCOPE__ .item--create:hover svg {
  height: 40px !important;
  width: 40px !important;
  margin-bottom: 5px;
}

.__UIV_SCOPE__ .item--create:hover {
  padding-top: 30px;
}

.__UIV_SCOPE__ .item--post::before {
  content: "";
  background-color: rgb(114, 7, 79);
  width: 230px;
  height: 230px;
  position: absolute;
  top: 0px;
  z-index: -2;
   /* top:200px;
   left:calc(50% - 50px); */
}

.__UIV_SCOPE__ .item--post {
  min-width: 230px;
  min-height: 230px;
  position: absolute;
  top: calc(50% - 130px);
  left: calc(50% - 120px);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 140px;
  transition: padding-top 0.5s ease-out;
  z-index: 99;
  -webkit-mask-image: url('data:image/svg+xml;base64,');
  -webkit-mask-repeat: no-repeat;
}

.__UIV_SCOPE__ .item--post svg {
  height: 50px !important;
  width: 50px !important;
  margin-bottom: 15px;
  transition: height 0.5s ease-out,width 0.5s ease-out,margin-bottom 0.5s ease-out;
}

.__UIV_SCOPE__ .item--post:hover svg {
  height: 40px !important;
  width: 40px !important;
  margin-bottom: 5px;
}

.__UIV_SCOPE__ .item--post:hover {
  padding-top: 130px;
}

.__UIV_SCOPE__ .item--inspire::before {
    /* background-image: url('data:image/svg+xml;base64,'); */
  content: "";
  background-color: rgb(179, 4, 100);
  width: 350px;
  height: 350px;
  position: absolute;
  top: 0px;
  z-index: -3;
   /* top:200px;
   left:calc(50% - 50px); */
}

.__UIV_SCOPE__ .item--inspire {
  min-width: 350px;
  min-height: 350px;
  position: absolute;
  top: calc(50% - 145px);
  left: calc(50% - 350px / 2);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 245px;
  transition: padding-top 0.5s ease-out;
  z-index: 98;
  -webkit-mask-image: url('data:image/svg+xml;base64,');
  -webkit-mask-repeat: no-repeat;
}

.__UIV_SCOPE__ .item--inspire svg {
  height: 50px !important;
  width: 50px !important;
  margin-bottom: 15px;
  transition: height 0.5s ease-out,width 0.5s ease-out,margin-bottom 0.5s ease-out;
}

.__UIV_SCOPE__ .item--inspire:hover svg {
  height: 40px !important;
  width: 40px !important;
  margin-bottom: 5px;
}

.__UIV_SCOPE__ .item--inspire:hover {
  padding-top: 232px;
}
